class Solution {
public:
    int sumOfBlocks(int n) {
        const long long MOD = 1000000007LL;
        long long next = 1, ans = 0;
        for (int len = 1; len <= n; ++len) {
            long long prod = 1;
            for (int j = 0; j < len; ++j) {
                prod = prod * (next++ % MOD) % MOD;
            }
            ans = (ans + prod) % MOD;
        }
        return (int)ans;
    }
};
